const { query, label, maxResults, pageToken } = $.input;
const max = Math.max(1, Math.min(100, maxResults || 10));

let q = '';
if (label) q += 'label:' + label;
if (query) q += (q ? ' ' : '') + query;

const params = { maxResults: String(max) };
if (q) params.q = q;
if (pageToken) params.pageToken = pageToken;

return { params, q, max };

const resp = $.steps.listMessages.response || {};
const messages = resp.messages || [];
return { messageRefs: messages, count: messages.length, nextPageToken: resp.nextPageToken || null };

const resp = $.steps.getMessage?.response;
if (!resp || !resp.payload) return null;

const headers = resp.payload.headers || [];
const getH = (name) => (headers.find(h => h.name.toLowerCase() === name.toLowerCase()) || {}).value || '';

function decodeBase64Url(data) {
  try {
    const fixed = data.replace(/-/g, '+').replace(/_/g, '/');
    const padded = fixed + '='.repeat((4 - fixed.length % 4) % 4);
    return atob(padded);
  } catch { return ''; }
}

function extractBody(payload) {
  if (payload.body && payload.body.data) return decodeBase64Url(payload.body.data);
  if (payload.parts) {
    for (const p of payload.parts) {
      if (p.mimeType === 'text/plain' && p.body && p.body.data) return decodeBase64Url(p.body.data);
    }
    for (const p of payload.parts) {
      if (p.mimeType === 'text/html' && p.body && p.body.data) return decodeBase64Url(p.body.data);
    }
    for (const p of payload.parts) {
      if (p.parts) {
        const nested = extractBody(p);
        if (nested) return nested;
      }
    }
  }
  return resp.snippet || '';
}

const body = extractBody(resp.payload);
const maxLen = 2000;

return {
  messageId: resp.id,
  threadId: resp.threadId || '',
  labelIds: resp.labelIds || [],
  from: getH('From'),
  to: getH('To'),
  subject: getH('Subject'),
  date: getH('Date'),
  snippet: resp.snippet || body.substring(0, 100),
  body: body.length > maxLen ? body.substring(0, maxLen) + '...' : body,
  historyId: resp.historyId || '',
  internalDate: resp.internalDate || ''
};

const iterations = $.steps.fetchMessages?.response?.iterations || [];
const emails = iterations.map(r => r?.parseMessage?.output).filter(Boolean);
const nextPageToken = $.steps.checkResults.output.nextPageToken;
const q = $.steps.buildQuery.output.q;
const max = $.steps.buildQuery.output.max;

const result = {
  emails,
  totalFound: emails.length,
  requestedCount: max,
  query: q || 'No query specified',
  summary: `Retrieved ${emails.length} email${emails.length === 1 ? '' : 's'}${q ? ' matching "' + q + '"' : ''}`
};

if (nextPageToken) result.nextPageToken = nextPageToken;

return result;
